152	    /**
153	     * The maximum number of owners that may be created in a single day. Creating an owner once this
154	     * many owners already carry today's {@code registrationDate} is rejected.
155	     */
156	    private static final int DAILY_OWNER_LIMIT = 100;
157	
158	    /**
159	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
160	     * given business day as their {@code registrationDate}. The count is keyed by the
161	     * business-day-adjusted registration date of the owner being created (see
162	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
163	     * with no {@code registrationDate} are ignored.
164	     *
165	     * @param registrationDate the business-day-adjusted registration date of the owner being created
166	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
167	     */
168	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
169	        long count = this.clinicService.findAllOwners().stream()
170	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
171	            .count();
172	        if (count >= DAILY_OWNER_LIMIT) {
173	            throw new DailyOwnerLimitException(registrationDate);
174	        }
175	    }
176	
177	    /**
178	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
179	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
180	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
181	     */
182	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
183	
184	    /**
185	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
186	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
187	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
188	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
189	     * owner being created is excluded (it has not yet been saved).
190	     *
191	     * @param registrationDate the business-day-adjusted registration date of the owner being created
192	     * @return {@code true} if more than the threshold of owners already carry this business day
193	     */
194	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
195	        long count = this.clinicService.findAllOwners().stream()
196	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
